   AND emp35_person_id  = #{personId}
 ORDER BY emp35_start_date DESC

SELECT 
  FROM emp35_deduct
 WHERE emp35_start_date = (
           SELECT MAX(emp35_start_date)
             FROM emp35_deduct
            WHERE emp35_company_id = #{companyId}
              AND emp35_start_date <= #{startDate}
              AND emp35_person_id  = #{personId}
       )
   AND emp35_company_id = #{companyId}
   AND emp35_person_id  = #{personId}

